function g(parent=scene){const o=new THREE.Group();parent.add(o);return o;}
function mesh(geo,m,p,x=0,y=0,z=0){const o=new THREE.Mesh(geo,typeof m==='string'?materials[m]:m);o.position.set(x,y,z);o.castShadow=true;o.receiveShadow=true;p.add(o);return o;}
function box(w,h,d,m,p,x=0,y=0,z=0){return mesh(new THREE.BoxGeometry(w,h,d),m,p,x,y,z);}
function cyl(r,h,m,p,x=0,y=0,z=0){return mesh(new THREE.CylinderGeometry(r,r,h,20),m,p,x,y,z);}
function sphere(r,m,p){return mesh(new THREE.SphereGeometry(r,16,12),m,p);}
function segment(a,b,r,m,p){const o=cyl(r,1,m,p);const A=new THREE.Vector3(...a),B=new THREE.Vector3(...b),v=B.clone().sub(A);o.position.copy(A).add(B).multiplyScalar(.5);o.scale.y=v.length();o.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),v.normalize());return o;}
function poly(points,color,parent){const o=new THREE.Line(new THREE.BufferGeometry().setFromPoints(points.map(p=>new THREE.Vector3(...p))),new THREE.LineBasicMaterial({color}));parent.add(o);return o;}
function sign(text,sub,w,h,parent,x,y,z){const c=document.createElement('canvas');c.width=768;c.height=256;const ctx=c.getContext('2d');ctx.fillStyle='#102d47';ctx.fillRect(0,0,768,256);ctx.fillStyle='#68d9d3';ctx.fillRect(30,40,8,175);ctx.fillStyle='#edf6fb';ctx.font='bold 58px sans-serif';ctx.fillText(text,60,110);ctx.fillStyle='#a9c4d5';ctx.font='25px sans-serif';ctx.fillText(sub,60,179);const texture=new THREE.CanvasTexture(c);texture.colorSpace=THREE.SRGBColorSpace;return mesh(new THREE.PlaneGeometry(w,h),new THREE.MeshBasicMaterial({map:texture,side:THREE.DoubleSide}),parent,x,y,z);}
