function conveyor(root,cx,cz,length=3.6,width=1.2,height=.8){const o=g(root);o.position.set(cx,0,cz);box(length,.15,width,'steel',o,0,height,0);for(let x=-length/2+.1;x<length/2;x+=.19){const r=cyl(.045,width-.14,'steel',o,x,height+.11,0);r.rotation.x=Math.PI/2;}for(const x of [-length/2+.2,length/2-.2])for(const z of [-width/2+.1,width/2-.1])box(.07,height,.07,'steel',o,x,height/2,z);for(const z of [-width/2,width/2])box(length,.12,.045,'dark',o,0,height+.13,z);box(.14,.14,.1,'dark',o,length/2-.2,height+.26,width/2);return o;}
