function pallet(root,x,z){const o=g(root);o.position.set(x,.06,z);for(const zz of [-.55,0,.55])box(1.45,.12,.15,'box',o,0,0,zz);for(const xx of [-.55,0,.55])box(.13,.18,1.3,'box',o,xx,.12,0);for(let zz=-.55;zz<.6;zz+=.22)box(1.45,.07,.18,'box',o,0,.24,zz);return o;}
