function part(root,type='metal'){const o=g(root);if(type==='pin'){cyl(.07,.36,'steel',o);cyl(.11,.065,'dark',o,0,.14,0);}else{cyl(.19,.25,'steel',o);cyl(.09,.29,'dark',o);cyl(.23,.045,'steel',o,0,-.1,0);}return o;}
